="alamat">Alamat</label><textarea class="input" id="alamat" name="alamat" rows="3" placeholder="Alamat tempat tinggal siswa"><?= e($data['alamat']) ?></textarea></div></div><div class="form-actions"><span class="required-note"><span>*</span> Wajib diisi</span><div><a class="btn btn-outline" href="index.php">Batal</a> <button class="btn btn-primary" type="submit">Simpan data <span>→</span></button></div></div></form>
